cat > /workspace/src/counter.go << 'GOEOF'
package main

import (
	"bufio"
	"bytes"
	"io"
	"strings"
)

// LineStats holds statistics for a single file or language
type LineStats struct {
	Lines    int `json:"lines"`
	Code     int `json:"code"`
	Comments int `json:"comments"`
	Blanks   int `json:"blanks"`
}

func (s LineStats) Total() int {
	return s.Code + s.Comments + s.Blanks
}

// CountFile counts lines in a file given its content and language
func CountFile(content []byte, lang *Language) (LineStats, map[string]LineStats) {
	reader := bytes.NewReader(content)
	return countLines(reader, lang)
}

// lineType represents the classification of a line
type lineClass int

const (
	lineBlank   lineClass = iota
	lineCode
	lineComment
)

// lineState holds the parser state across lines
type lineState struct {
	inMLComment int  // depth of multi-line comment nesting (0 = not in ML comment)
	inString    bool // in string
}

// classifyLine determines if a line is code, comment, or blank
// given the current state (whether we're inside a ML comment at start)
// Returns: classification, new inMLComment depth
func classifyLine(line string, comment CommentStyle, state *lineState) lineClass {
	if comment.MultiOpen == nil && comment.Single == nil {
		// No comment support, just check if blank
		if strings.TrimSpace(line) == "" {
			return lineBlank
		}
		return lineCode
	}

	// If we're starting inside a ML comment, this line is a comment
	if state.inMLComment > 0 {
		// Scan for end of ML comment
		idx := 0
		for idx < len(line) {
			// Check for comment end
			closed := false
			for ci, close := range comment.MultiClose {
				if idx+len(close) <= len(line) && line[idx:idx+len(close)] == close {
					if comment.NestedComments {
						state.inMLComment--
						if state.inMLComment == 0 {
							closed = true
						}
					} else {
						state.inMLComment = 0
						closed = true
					}
					_ = ci
					if closed {
						idx += len(close)
						break
					}
				}
			}
			if !closed {
				// Check for nested comment open
				if comment.NestedComments {
					foundOpen := false
					for _, open := range comment.MultiOpen {
						if idx+len(open) <= len(line) && line[idx:idx+len(open)] == open {
							state.inMLComment++
							idx += len(open)
							foundOpen = true
							break
						}
					}
					if !foundOpen {
						idx++
					}
				} else {
					idx++
				}
			}
		}
		return lineComment
	}

	trimmed := strings.TrimSpace(line)
	if trimmed == "" {
		return lineBlank
	}

	// Parse the line
	// Track: position of first comment start, position after last ML comment close
	firstCommentStart := len(line)  // position of first comment marker
	lastMLClose := -1               // position after last */ 
	hasSLAfterML := false           // has SL comment after some ML comment

	idx := 0
	inML := 0

	// Check for strings? For now, we'll skip string detection for simplicity
	// This may cause some inaccuracies with strings containing comment markers

	for idx < len(line) {
		if inML > 0 {
			// In ML comment, look for end
			closed := false
			for _, close := range comment.MultiClose {
				if idx+len(close) <= len(line) && line[idx:idx+len(close)] == close {
					if comment.NestedComments {
						inML--
						if inML == 0 {
							lastMLClose = idx + len(close)
							closed = true
						}
					} else {
						inML = 0
						lastMLClose = idx + len(close)
						closed = true
					}
					if closed {
						idx += len(close)
						break
					}
				}
			}
			if !closed {
				// Check for nested open
				if comment.NestedComments {
					foundOpen := false
					for _, open := range comment.MultiOpen {
						if idx+len(open) <= len(line) && line[idx:idx+len(open)] == open {
							inML++
							idx += len(open)
							foundOpen = true
							break
						}
					}
					if !foundOpen {
						idx++
					}
				} else {
					idx++
				}
			}
		} else {
			// OUT state - check for comment starters
			foundComment := false

			// Check ML comment openers
			for _, open := range comment.MultiOpen {
				if idx+len(open) <= len(line) && line[idx:idx+len(open)] == open {
					if idx < firstCommentStart {
						firstCommentStart = idx
					}
					inML++
					idx += len(open)
					foundComment = true
					break
				}
			}
			if foundComment {
				continue
			}

			// Check SL comment markers
			for _, sl := range comment.Single {
				if idx+len(sl) <= len(line) && line[idx:idx+len(sl)] == sl {
					if idx < firstCommentStart {
						firstCommentStart = idx
					}
					// SL comment - rest of line is comment
					if lastMLClose >= 0 {
						hasSLAfterML = true
					}
					// Jump to end
					idx = len(line)
					foundComment = true
					break
				}
			}
			if foundComment {
				continue
			}

			idx++
		}
	}

	// Update state for next line
	state.inMLComment = inML

	// Determine classification
	// Check for code before first comment
	codeBeforeFirst := false
	for i := 0; i < firstCommentStart && i < len(line); i++ {
		if line[i] != ' ' && line[i] != '\t' {
			codeBeforeFirst = true
			break
		}
	}
	if codeBeforeFirst {
		return lineCode
	}

	// Check if line is blank (no content)
	if firstCommentStart == len(line) && strings.TrimSpace(line) == "" {
		return lineBlank
	}

	// Check for content after last ML close
	if lastMLClose >= 0 {
		// Is there anything non-whitespace after lastMLClose?
		for i := lastMLClose; i < len(line); i++ {
			if line[i] != ' ' && line[i] != '\t' {
				// There's content after last ML close
				return lineCode
			}
		}
		// Nothing after last ML close, but was there a SL comment after?
		if hasSLAfterML {
			return lineCode
		}
		return lineComment
	}

	// No ML comment closed, line is either blank, comment-only, or code
	if firstCommentStart < len(line) {
		return lineComment
	}
	return lineBlank
}

// countLines reads all lines and counts code/comment/blank
func countLines(r io.Reader) (LineStats, map[string]LineStats) {
	// This signature needs the language
	panic("use countLinesWithLang instead")
}

func countLinesWithLang(r io.Reader, lang *Language) (LineStats, map[string]LineStats) {
	scanner := bufio.NewScanner(r)
	scanner.Buffer(make([]byte, 1024*1024), 1024*1024)

	var stats LineStats
	children := make(map[string]LineStats)

	state := &lineState{}

	for scanner.Scan() {
		line := scanner.Text()
		stats.Lines++

		class := classifyLine(line, lang.Comment, state)
		switch class {
		case lineCode:
			stats.Code++
		case lineComment:
			stats.Comments++
		case lineBlank:
			stats.Blanks++
		}
	}

	return stats, children
}

// CountFileWithLang is the main function to count a file
func CountFileWithLang(content []byte, lang *Language) (LineStats, map[string]LineStats) {
	r := bytes.NewReader(content)
	return countLinesWithLang(r, lang)
}
GOEOF

