import subprocess, re

# Get all 327 languages with their extensions (but some are truncated)
# Let me compile a comprehensive list by testing extensions

result = subprocess.run(['./executable', '--languages'], capture_output=True, text=True)
data = result.stdout

langs = {}
for line in data.split('\n'):
    line = line.strip()
    if not (line.startswith('┃') and line.endswith('┃')):
        continue
    content = line[1:-1].strip()
    if not content or 'Language' in content or '━' in content:
        continue
    parts = re.split(r'  {2,}', content)
    parts = [p.strip() for p in parts if p.strip()]
    if len(parts) >= 2:
        name = parts[0]
        exts_str = parts[-1]
        truncated = exts_str.endswith('...')
        if truncated:
            exts_str = exts_str[:-3].rstrip(' ,')
        exts = [e.strip() for e in exts_str.split(',') if e.strip()]
        langs[name] = {'exts': exts, 'truncated': truncated}
    elif len(parts) == 1:
        langs[parts[0]] = {'exts': [], 'truncated': False}

# Show truncated ones
print("Truncated extensions:")
for name, info in langs.items():
    if info['truncated']:
        print(f'  {name}: {info["exts"]}')
EOF

