}

// FileReport holds stats for a single file
type FileReport struct {
	Name  string             `json:"name"`
	Stats LineStats          `json:"stats"`
}

// MarshalJSON custom marshaling for FileReport
func (f FileReport) MarshalJSON() ([]byte, error) {
	type Alias struct {
		Stats struct {
			Blanks   int            `json:"blanks"`
			Code     int            `json:"code"`
			Comments int            `json:"comments"`
			Blobs    map[string]LineStats `json:"blobs"`
		} `json:"stats"`
		Name string `json:"name"`
	}
	a := Alias{}
	a.Name = f.Name
	a.Stats.Blanks = f.Stats.Blanks
	a.Stats.Code = f.Stats.Code
	a.Stats.Comments = f.Stats.Comments
	a.Stats.Blobs = f.Stats.Children
	return json.Marshal(a)
}

// LanguageStats holds aggregated stats for a language
type LanguageStats struct {
	Blanks   int                         `json:"blanks"`
	Code     int                         `json:"code"`
	Comments int                         `json:"comments"`
	Reports  []FileReport                `json:"reports"`
	Children map[string][]FileReport     `json:"children"`
	Inaccurate bool                      `json:"inaccurate"`
}

func newLanguageStats() LanguageStats {
	return LanguageStats{
		Reports:  []FileReport{},
		Children: map[string][]FileReport{},
	}
}

func (s LanguageStats) Lines() int {
	return s.Code + s.Comments + s.Blanks
}

func (s LanguageStats) Files() int {
	return len(s.Reports)
}

func main() {
	cfg := parseArgs(os.Args[1:])

	if cfg.Languages {
		printLanguages()
		return
	}

	// Determine terminal width for columns
	if cfg.Columns == 0 {
		cfg.Columns = 81 // default
	}

	// Filter languages if --types is specified
	var langFilter map[string]bool
	if len(cfg.Types) > 0 {
		langFilter = make(map[string]bool)
		for _, t := range cfg.Types {
			langFilter[t] = true
		}
	}

	// Collect stats
	stats := make(map[string]LanguageStats)

	paths := cfg.Paths
	if len(paths) == 0 {
		paths = []string{"."}
	}

	// Process paths
	for _, path := range paths {
		fi, err := os.Stat(path)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: %q not found.\n", path)
			os.Exit(1)
		}

		if fi.IsDir() {
			// Walk directory
			ignorer := NewIgnorer(path, cfg)
			walkDir(path, path, ignorer, cfg, langFilter, stats)
		} else {
			// Single file
			processFile(path, path, cfg, langFilter, stats)
		}
	}

	if cfg.Output == "json" {
		outputJSON(stats)
		return
	}

	if cfg.Streaming == "json" || cfg.Streaming == "simple" {
		outputStreaming(stats, cfg.Streaming)
		return
	}

	// Print table
	printTable(stats, cfg)
}

