func getSortedLangNames(stats map[string]LanguageStats, sortBy string, rsortBy string) []string {
	names := make([]string, 0, len(stats))
	for k := range stats {
		names = append(names, k)
	}

	sortField := sortBy
	if rsortBy != "" {
		sortField = rsortBy
	}

	switch sortField {
	case "files":
		sort.Slice(names, func(i, j int) bool {
			a, b := stats[names[i]].Files(), stats[names[j]].Files()
			if a != b {
				if rsortBy != "" {
					return a > b
				}
				return a < b
			}
			return names[i] < names[j]
		})
	case "lines":
		sort.Slice(names, func(i, j int) bool {
			a, b := stats[names[i]].Lines(), stats[names[j]].Lines()
			if a != b {
				if rsortBy != "" {
					return a > b
				}
				return a < b
			}
			return names[i] < names[j]
		})
	case "code":
		sort.Slice(names, func(i, j int) bool {
			a, b := stats[names[i]].Code, stats[names[j]].Code
			if a != b {
				if rsortBy != "" {
					return a > b
				}
				return a < b
			}
			return names[i] < names[j]
		})
	case "comments":
		sort.Slice(names, func(i, j int) bool {
			a, b := stats[names[i]].Comments, stats[names[j]].Comments
			if a != b {
				if rsortBy != "" {
					return a > b
				}
				return a < b
			}
			return names[i] < names[j]
		})
	case "blanks":
		sort.Slice(names, func(i, j int) bool {
			a, b := stats[names[i]].Blanks, stats[names[j]].Blanks
			if a != b {
				if rsortBy != "" {
					return a > b
				}
				return a < b
			}
			return names[i] < names[j]
		})
	default:
		// Default: alphabetical by language name
		sort.Strings(names)
	}

	return names
}

func formatNum(n int, style string) string {
	s := strconv.Itoa(n)
	if style == "" || style == "plain" {
		return s
	}

	// Add separators
	var sep string
	switch style {
	case "commas":
		sep = ","
	case "dots":
		sep = "."
	case "underscores":
		sep = "_"
	default:
		return s
	}

	// Insert separators every 3 digits from right
	runes := []rune(s)
	result := make([]rune, 0, len(runes)*2)
	for i, r := range runes {
		pos := len(runes) - i
		if i > 0 && pos%3 == 0 {
			result = append(result, []rune(sep)...)
		}
		result = append(result, r)
	}
	return string(result)
}

func printTable(stats map[string]LanguageStats, cfg Config) {
	cols := cfg.Columns
	langW := cols - 67 // lang column width
	if langW < 1 {
		langW = 1
	}

	thick := strings.Repeat("━", cols)
	thin := strings.Repeat("─", cols)

	// Header
	fmt.Println(thick)
	header := " " + padRight("Language", langW) + padLeft("Files", 13) + padLeft("Lines", 13) + padLeft("Code", 13) + padLeft("Comments", 13) + padLeft("Blanks", 13)
	fmt.Println(header)
	fmt.Println(thick)

	// Get sorted language names
	langNames := getSortedLangNames(stats, cfg.Sort, cfg.Rsort)

	// Track total
	var totalCode, totalComments, totalBlanks, totalFiles int
	totalChildFiles := make(map[string]int)
	totalChildCode := make(map[string]int)
	totalChildComments := make(map[string]int)
	totalChildBlanks := make(map[string]int)

	for _, langName := range langNames {
		ls := stats[langName]
		totalCode += ls.Code
		totalComments += ls.Comments
		totalBlanks += ls.Blanks
		totalFiles += ls.Files()

		files := ls.Files()
		lines := ls.Lines()
		fmt.Printf(" %s%s%s%s%s%s\n",
			padRight(langName, langW),
			padLeft(formatNum(files, cfg.NumFormat), 13),
			padLeft(formatNum(lines, cfg.NumFormat), 13),
			padLeft(formatNum(ls.Code, cfg.NumFormat), 13),
			padLeft(formatNum(ls.Comments, cfg.NumFormat), 13),
			padLeft(formatNum(ls.Blanks, cfg.NumFormat), 13))

		// Print child languages if not compact
		if !cfg.Compact && len(ls.Children) > 0 {
			// Sort child language names
			childNames := make([]string, 0, len(ls.Children))
			for cn := range ls.Children {
				childNames = append(childNames, cn)
			}
			sort.Strings(childNames)

			for _, cn := range childNames {
				childReports := ls.Children[cn]
				var cCode, cComments, cBlanks int
				for _, r := range childReports {
					cCode += r.Stats.Code
					cComments += r.Stats.Comments
					cBlanks += r.Stats.Blanks
				}
				cFiles := len(childReports)
				cLines := cCode + cComments + cBlanks

				totalChildFiles[cn] += cFiles
				totalChildCode[cn] += cCode
				totalChildComments[cn] += cComments
				totalChildBlanks[cn] += cBlanks

				childLabel := "|- " + cn
				fmt.Printf(" %s%s%s%s%s%s\n",
					padRight(childLabel, langW),
					padLeft(formatNum(cFiles, cfg.NumFormat), 13),
					padLeft(formatNum(cLines, cfg.NumFormat), 13),
					padLeft(formatNum(cCode, cfg.NumFormat), 13),
					padLeft(formatNum(cComments, cfg.NumFormat), 13),
					padLeft(formatNum(cBlanks, cfg.NumFormat), 13))
			}

			// Print (Total) row
			totalChildCode2 := ls.Code
			totalChildComments2 := ls.Comments
			totalChildBlanks2 := ls.Blanks
			totalChildLines2 := ls.Lines()

			for _, childReports := range ls.Children {
				for _, r := range childReports {
					totalChildCode2 += r.Stats.Code
					totalChildComments2 += r.Stats.Comments
					totalChildBlanks2 += r.Stats.Blanks
					totalChildLines2 += r.Stats.Lines()
				}
			}

			fmt.Printf(" %s%s%s%s%s%s\n",
				padRight("(Total)", langW),
				padLeft("", 13),
				padLeft(formatNum(totalChildLines2, cfg.NumFormat), 13),
				padLeft(formatNum(totalChildCode2, cfg.NumFormat), 13),
				padLeft(formatNum(totalChildComments2, cfg.NumFormat), 13),
				padLeft(formatNum(totalChildBlanks2, cfg.NumFormat), 13))
		}

		// Print individual files if --files
		if cfg.Files {
			fmt.Println(thin)
			for _, report := range ls.Reports {
				if len(report.Stats.Children) > 0 {
					// This file has child languages
					fmt.Printf(" %s\n", report.Name)
					childNames2 := make([]string, 0)
					for cn := range report.Stats.Children {
						childNames2 = append(childNames2, cn)
					}
					sort.Strings(childNames2)

					for _, cn := range childNames2 {
						cs := report.Stats.Children[cn]
						childLabel := "|- " + cn
						cLines := cs.Lines()
						fmt.Printf(" %s%s%s%s%s\n",
							padRight(childLabel, langW+13),
							padLeft(formatNum(cLines, cfg.NumFormat), 13),
							padLeft(formatNum(cs.Code, cfg.NumFormat), 13),
							padLeft(formatNum(cs.Comments, cfg.NumFormat), 13),
							padLeft(formatNum(cs.Blanks, cfg.NumFormat), 13))
					}
					// Main file total
					fileLines := report.Stats.Lines()
					fmt.Printf(" %s%s%s%s%s\n",
						padRight(report.Name, langW+13),
						padLeft(formatNum(fileLines, cfg.NumFormat), 13),
						padLeft(formatNum(report.Stats.Code, cfg.NumFormat), 13),
						padLeft(formatNum(report.Stats.Comments, cfg.NumFormat), 13),
						padLeft(formatNum(report.Stats.Blanks, cfg.NumFormat), 13))
				} else {
					fileLines := report.Stats.Lines()
					fmt.Printf(" %s%s%s%s%s\n",
						padRight(report.Name, langW+13),
						padLeft(formatNum(fileLines, cfg.NumFormat), 13),
						padLeft(formatNum(report.Stats.Code, cfg.NumFormat), 13),
						padLeft(formatNum(report.Stats.Comments, cfg.NumFormat), 13),
						padLeft(formatNum(report.Stats.Blanks, cfg.NumFormat), 13))
				}
			}
		}

		// Separator between languages (only if --files)
		if cfg.Files {
			_ = thin // already printed above
		}
	}

	// Compute grand total children
	for _, ls := range stats {
		for cn, childReports := range ls.Children {
			for _, r := range childReports {
				totalCode += r.Stats.Code
				totalComments += r.Stats.Comments
				totalBlanks += r.Stats.Blanks
			}
			_ = cn
		}
	}

	// Grand total
	fmt.Println(thick)
	totalLines := totalCode + totalComments + totalBlanks
	fmt.Printf(" %s%s%s%s%s%s\n",
		padRight("Total", langW),
		padLeft(formatNum(totalFiles, cfg.NumFormat), 13),
		padLeft(formatNum(totalLines, cfg.NumFormat), 13),
		padLeft(formatNum(totalCode, cfg.NumFormat), 13),
		padLeft(formatNum(totalComments, cfg.NumFormat), 13),
		padLeft(formatNum(totalBlanks, cfg.NumFormat), 13))
	fmt.Println(thick)
}

func padRight(s string, width int) string {
	// Pad string to width using Unicode-aware length
	l := utf8.RuneCountInString(s)
	if l >= width {
		if width > 3 {
			runes := []rune(s)
			if len(runes) > width {
				return string(runes[:width])
			}
		}
		return s
	}
	return s + strings.Repeat(" ", width-l)
}

func padLeft(s string, width int) string {
	l := utf8.RuneCountInString(s)
	if l >= width {
		return s
	}
	return strings.Repeat(" ", width-l) + s
}

func printLanguages() {
	outer := "━"
	inner := "┃"

	outerWidth := 72
	innerWidth := 70
	nameW := 37
	extW := 31

	fmt.Println(strings.Repeat(outer, outerWidth))
	fmt.Printf("%s %s%s %s%s%s\n", inner,
		padRight("Language", nameW), " ",
		padRight("Extensions", extW),
		inner)
	fmt.Printf("%s%s%s\n", inner, strings.Repeat(outer, innerWidth), inner)

	// Get all languages sorted
	langs := getAllLanguagesSorted()

	for _, lang := range langs {
		exts := lang.Extensions
		extStr := strings.Join(exts, ", ")
		if len(extStr) > 30 {
			extStr = extStr[:27] + "..."
		}
		if extStr == "" {
			extStr = "<None>"
		}

		fmt.Printf("%s %s%s %s%s%s\n", inner,
			padRight(lang.Name, nameW), " ",
			padRight(extStr, extW-1)+" ",
			inner)
	}

	fmt.Println(strings.Repeat(outer, outerWidth))
	fmt.Println()
}

func getAllLanguagesSorted() []Language {
	var result []Language
	for i := range Languages {
		if len(Languages[i].Extensions) > 0 || len(Languages[i].Filenames) > 0 {
			result = append(result, Languages[i])
		}
	}
	// Sort alphabetically (case insensitive)
	sort.Slice(result, func(i, j int) bool {
		return strings.ToLower(result[i].Name) < strings.ToLower(result[j].Name)
	})
	return result
}
