func walkDir(baseDir, dir string, ignorer *Ignorer, cfg Config, langFilter map[string]bool, stats map[string]LanguageStats) {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return
	}

	for _, entry := range entries {
		name := entry.Name()
		path := filepath.Join(dir, name)

		// Skip hidden files/dirs unless --hidden
		if !cfg.Hidden && strings.HasPrefix(name, ".") {
			continue
		}

		// Check exclude patterns
		if matchesExclude(path, name, cfg.Exclude) {
			continue
		}

		if entry.IsDir() {
			// Check if ignored
			if ignorer != nil && ignorer.IsIgnored(path, true) {
				continue
			}
			// Recurse
			subIgnorer := ignorer
			if ignorer != nil {
				subIgnorer = ignorer.ForSubdir(path, cfg)
			}
			walkDir(baseDir, path, subIgnorer, cfg, langFilter, stats)
		} else {
			// Check if ignored
			if ignorer != nil && ignorer.IsIgnored(path, false) {
				continue
			}
			processFile(path, path, cfg, langFilter, stats)
		}
	}
}

func matchesExclude(path, name string, patterns []string) bool {
	for _, pattern := range patterns {
		// Simple glob matching
		if matchGlob(pattern, name) || matchGlob(pattern, path) {
			return true
		}
		// Also try just the base name
		base := filepath.Base(path)
		if matchGlob(pattern, base) {
			return true
		}
	}
	return false
}

func matchGlob(pattern, name string) bool {
	// Simple glob: * matches any sequence of non-separator characters
	matched, _ := filepath.Match(pattern, name)
	if matched {
		return true
	}
	// Also try matching just the base name
	matched, _ = filepath.Match(pattern, filepath.Base(name))
	return matched
}

func processFile(path, displayPath string, cfg Config, langFilter map[string]bool, stats map[string]LanguageStats) {
	lang := DetectLanguage(path)
	if lang == nil {
		if cfg.Verbose >= 1 {
			fmt.Fprintf(os.Stderr, "Unknown extension: %s\n", filepath.Ext(path))
		}
		return
	}

	// Apply language filter
	if langFilter != nil && !langFilter[lang.Name] {
		return
	}

	content, err := os.ReadFile(path)
	if err != nil {
		return
	}

	fileStats, childMap := CountFileWithLang(content, lang)

	// Create file report
	report := FileReport{
		Name:  displayPath,
		Stats: fileStats,
	}

	// Update language stats
	ls := stats[lang.Name]
	if ls.Reports == nil {
		ls = newLanguageStats()
	}
	ls.Blanks += fileStats.Blanks
	ls.Code += fileStats.Code
	ls.Comments += fileStats.Comments
	ls.Reports = append(ls.Reports, report)

	// Add children
	for childLang, childStats := range childMap {
		childReport := FileReport{
			Name:  displayPath,
			Stats: childStats,
		}
		ls.Children[childLang] = append(ls.Children[childLang], childReport)
	}

	stats[lang.Name] = ls
}

func outputJSON(stats map[string]LanguageStats) {
	// Build total
	total := newLanguageStats()
	total.Reports = []FileReport{}

	allChildren := make(map[string][]FileReport)

	for langName, ls := range stats {
		total.Blanks += ls.Blanks
		total.Code += ls.Code
		total.Comments += ls.Comments
		for childLang, reports := range ls.Children {
			allChildren[childLang] = append(allChildren[childLang], reports...)
		}
		_ = langName
	}
	total.Children = allChildren

	// Build output map
	out := make(map[string]LanguageStats)
	for k, v := range stats {
		out[k] = v
	}
	out["Total"] = total

	// Sort by key for consistent output
	data, _ := json.Marshal(out)
	fmt.Print(string(data))
}

func outputStreaming(stats map[string]LanguageStats, format string) {
	type streamRecord struct {
		lang  string
		path  string
		lines int
		code  int
		comments int
		blanks int
	}

	var records []streamRecord

	for langName, ls := range stats {
		for _, report := range ls.Reports {
			records = append(records, streamRecord{
				lang:     langName,
				path:     report.Name,
				lines:    report.Stats.Lines(),
				code:     report.Stats.Code,
				comments: report.Stats.Comments,
				blanks:   report.Stats.Blanks,
			})
		}
	}

	// Sort by lang name, then path
	sort.Slice(records, func(i, j int) bool {
		if records[i].lang != records[j].lang {
			return records[i].lang < records[j].lang
		}
		return records[i].path < records[j].path
	})

	if format == "json" {
		for _, r := range records {
			type StreamJSON struct {
				Language string `json:"language"`
				Stats    struct {
					Name  string    `json:"name"`
					Stats LineStats `json:"stats"`
				} `json:"stats"`
			}
			sj := StreamJSON{Language: r.lang}
			sj.Stats.Name = r.path
			sj.Stats.Stats = LineStats{
				Blanks:   r.blanks,
				Code:     r.code,
				Comments: r.comments,
			}
			data, _ := json.Marshal(sj)
			fmt.Println(string(data))
		}
	} else {
		// Simple format
		// Header
		langW := 10
		pathW := 80
		numW := 13
		sep1 := strings.Repeat("#", langW)
		sep2 := strings.Repeat("#", pathW)
		sep3 := strings.Repeat("#", numW-1)

		header := "# " + "language" + strings.Repeat(" ", langW-2-8) +
			" " + "path" + strings.Repeat(" ", pathW-4) +
			strings.Repeat(" ", numW-len("lines")) + "lines" +
			strings.Repeat(" ", numW-len("code")) + "code" +
			strings.Repeat(" ", numW-len("comments")) + "comments" +
			strings.Repeat(" ", numW-len("blanks")) + "blanks" +
			"   "
		fmt.Println(header)
		fmt.Printf("%s %s %s %s %s %s\n", sep1, sep2, sep3, sep3, sep3, sep3)

		for _, r := range records {
			langPart := fmt.Sprintf("%*s", langW, r.lang)
			pathPart := fmt.Sprintf("%-*s", pathW, r.path)
			linesPart := fmt.Sprintf("%*d", numW, r.lines)
			codePart := fmt.Sprintf("%*d", numW, r.code)
			commentsPart := fmt.Sprintf("%*d", numW, r.comments)
			blanksPart := fmt.Sprintf("%*d", numW, r.blanks)
			fmt.Printf("%s %s%s%s%s%s\n", langPart, pathPart, linesPart, codePart, commentsPart, blanksPart)
		}
	}
}

func getSortedLangNames(stats map[string]LanguageStats, sortBy string, rsortBy string) []string {
	names := make([]string, 0, len(stats))
	for k := range stats {
		names = append(names, k)
	}

	sortField := sortBy
	if rsortBy != "" {
		sortField = rsortBy
	}

	switch sortField {
	case "files":
		sort.Slice(names, func(i, j int) bool {
			a, b := stats[names[i]].Files(), stats[names[j]].Files()
			if a != b {
				if rsortBy != "" {
					return a > b
				}
				return a < b
			}
			return names[i] < names[j]
		})
	case "lines":
		sort.Slice(names, func(i, j int) bool {
			a, b := stats[names[i]].Lines(), stats[names[j]].Lines()
			if a != b {
				if rsortBy != "" {
					return a > b
				}
				return a < b
			}
			return names[i] < names[j]
		})
	case "code":
		sort.Slice(names, func(i, j int) bool {
			a, b := stats[names[i]].Code, stats[names[j]].Code
			if a != b {
				if rsortBy != "" {
					return a > b
				}
				return a < b
			}
			return names[i] < names[j]
		})
	case "comments":
		sort.Slice(names, func(i, j int) bool {
			a, b := stats[names[i]].Comments, stats[names[j]].Comments
			if a != b {
				if rsortBy != "" {
					return a > b
				}
				return a < b
			}
			return names[i] < names[j]
		})
	case "blanks":
		sort.Slice(names, func(i, j int) bool {
			a, b := stats[names[i]].Blanks, stats[names[j]].Blanks
			if a != b {
				if rsortBy != "" {
					return a > b
				}
				return a < b
			}
			return names[i] < names[j]
		})
	default:
		// Default: alphabetical by language name
		sort.Strings(names)
	}

	return names
}

func formatNum(n int, style string) string {
	s := strconv.Itoa(n)
	if style == "" || style == "plain" {
		return s
	}

	// Add separators
	var sep string
	switch style {
	case "commas":
		sep = ","
	case "dots":
		sep = "."
	case "underscores":
		sep = "_"
	default:
		return s
	}

	// Insert separators every 3 digits from right
	runes := []rune(s)
	result := make([]rune, 0, len(runes)*2)
	for i, r := range runes {
		pos := len(runes) - i
		if i > 0 && pos%3 == 0 {
			result = append(result, []rune(sep)...)
		}
		result = append(result, r)
	}
	return string(result)
}

func printTable(stats map[string]LanguageStats, cfg Config) {
	cols := cfg.Columns
	langW := cols - 67 // lang column width
	if langW < 1 {
		langW = 1
	}

	thick := strings.Repeat("━", cols)
	thin := strings.Repeat("─", cols)

	// Header
	fmt.Println(thick)
	header := " " + padRight("Language", langW) + padLeft("Files", 13) + padLeft("Lines", 13) + padLeft("Code", 13) + padLeft("Comments", 13) + padLeft("Blanks", 13)
	fmt.Println(header)
	fmt.Println(thick)

	// Get sorted language names
	langNames := getSortedLangNames(stats, cfg.Sort, cfg.Rsort)

	// Track total
	var totalCode, totalComments, totalBlanks, totalFiles int
	totalChildFiles := make(map[string]int)
	totalChildCode := make(map[string]int)
	totalChildComments := make(map[string]int)
	totalChildBlanks := make(map[string]int)

	for _, langName := range langNames {
		ls := stats[langName]
		totalCode += ls.Code
		totalComments += ls.Comments
		totalBlanks += ls.Blanks
		totalFiles += ls.Files()

		files := ls.Files()
		lines := ls.Lines()
		fmt.Printf(" %s%s%s%s%s%s\n",
			padRight(langName, langW),
			padLeft(formatNum(files, cfg.NumFormat), 13),
			padLeft(formatNum(lines, cfg.NumFormat), 13),
			padLeft(formatNum(ls.Code, cfg.NumFormat), 13),
			padLeft(formatNum(ls.Comments, cfg.NumFormat), 13),
			padLeft(formatNum(ls.Blanks, cfg.NumFormat), 13))

		// Print child languages if not compact
		if !cfg.Compact && len(ls.Children) > 0 {
			// Sort child language names
			childNames := make([]string, 0, len(ls.Children))
			for cn := range ls.Children {
				childNames = append(childNames, cn)
			}
			sort.Strings(childNames)

			for _, cn := range childNames {
				childReports := ls.Children[cn]
				var cCode, cComments, cBlanks int
				for _, r := range childReports {
					cCode += r.Stats.Code
					cComments += r.Stats.Comments
					cBlanks += r.Stats.Blanks
				}
				cFiles := len(childReports)
				cLines := cCode + cComments + cBlanks

				totalChildFiles[cn] += cFiles
				totalChildCode[cn] += cCode
				totalChildComments[cn] += cComments
				totalChildBlanks[cn] += cBlanks

				childLabel := "|- " + cn
				fmt.Printf(" %s%s%s%s%s%s\n",
					padRight(childLabel, langW),
					padLeft(formatNum(cFiles, cfg.NumFormat), 13),
					padLeft(formatNum(cLines, cfg.NumFormat), 13),
					padLeft(formatNum(cCode, cfg.NumFormat), 13),
					padLeft(formatNum(cComments, cfg.NumFormat), 13),
					padLeft(formatNum(cBlanks, cfg.NumFormat), 13))
			}

			// Print (Total) row
			totalChildCode2 := ls.Code
			totalChildComments2 := ls.Comments
			totalChildBlanks2 := ls.Blanks
			totalChildLines2 := ls.Lines()

			for _, childReports := range ls.Children {
				for _, r := range childReports {
					totalChildCode2 += r.Stats.Code
					totalChildComments2 += r.Stats.Comments
					totalChildBlanks2 += r.Stats.Blanks
					totalChildLines2 += r.Stats.Lines()
				}
			}

			fmt.Printf(" %s%s%s%s%s%s\n",
				padRight("(Total)", langW),
				padLeft("", 13),
				padLeft(formatNum(totalChildLines2, cfg.NumFormat), 13),
				padLeft(formatNum(totalChildCode2, cfg.NumFormat), 13),
				padLeft(formatNum(totalChildComments2, cfg.NumFormat), 13),
				padLeft(formatNum(totalChildBlanks2, cfg.NumFormat), 13))
		}

		// Print individual files if --files
		if cfg.Files {
			fmt.Println(thin)
			for _, report := range ls.Reports {
				if len(report.Stats.Children) > 0 {
					// This file has child languages
					fmt.Printf(" %s\n", report.Name)
					childNames2 := make([]string, 0)
					for cn := range report.Stats.Children {
						childNames2 = append(childNames2, cn)
					}
					sort.Strings(childNames2)

					for _, cn := range childNames2 {
						cs := report.Stats.Children[cn]
						childLabel := "|- " + cn
						cLines := cs.Lines()
						fmt.Printf(" %s%s%s%s%s\n",
							padRight(childLabel, langW+13),
							padLeft(formatNum(cLines, cfg.NumFormat), 13),
							padLeft(formatNum(cs.Code, cfg.NumFormat), 13),
							padLeft(formatNum(cs.Comments, cfg.NumFormat), 13),
							padLeft(formatNum(cs.Blanks, cfg.NumFormat), 13))
					}
					// Main file total
					fileLines := report.Stats.Lines()
					fmt.Printf(" %s%s%s%s%s\n",
						padRight(report.Name, langW+13),
						padLeft(formatNum(fileLines, cfg.NumFormat), 13),
						padLeft(formatNum(report.Stats.Code, cfg.NumFormat), 13),
						padLeft(formatNum(report.Stats.Comments, cfg.NumFormat), 13),
						padLeft(formatNum(report.Stats.Blanks, cfg.NumFormat), 13))
				} else {
					fileLines := report.Stats.Lines()
					fmt.Printf(" %s%s%s%s%s\n",
						padRight(report.Name, langW+13),
						padLeft(formatNum(fileLines, cfg.NumFormat), 13),
						padLeft(formatNum(report.Stats.Code, cfg.NumFormat), 13),
						padLeft(formatNum(report.Stats.Comments, cfg.NumFormat), 13),
						padLeft(formatNum(report.Stats.Blanks, cfg.NumFormat), 13))
				}
			}
		}

		// Separator between languages (only if --files)
		if cfg.Files {
			_ = thin // already printed above
		}
	}

	// Compute grand total children
	for _, ls := range stats {
		for cn, childReports := range ls.Children {
			for _, r := range childReports {
				totalCode += r.Stats.Code
				totalComments += r.Stats.Comments
				totalBlanks += r.Stats.Blanks
			}
			_ = cn
		}
	}

	// Grand total
	fmt.Println(thick)
	totalLines := totalCode + totalComments + totalBlanks
	fmt.Printf(" %s%s%s%s%s%s\n",
		padRight("Total", langW),
		padLeft(formatNum(totalFiles, cfg.NumFormat), 13),
		padLeft(formatNum(totalLines, cfg.NumFormat), 13),
		padLeft(formatNum(totalCode, cfg.NumFormat), 13),
		padLeft(formatNum(totalComments, cfg.NumFormat), 13),
		padLeft(formatNum(totalBlanks, cfg.NumFormat), 13))
	fmt.Println(thick)
}

func padRight(s string, width int) string {
	// Pad string to width using Unicode-aware length
	l := utf8.RuneCountInString(s)
	if l >= width {
		if width > 3 {
			runes := []rune(s)
			if len(runes) > width {
				return string(runes[:width])
			}
		}
		return s
	}
	return s + strings.Repeat(" ", width-l)
}

func padLeft(s string, width int) string {
	l := utf8.RuneCountInString(s)
	if l >= width {
		return s
	}
	return strings.Repeat(" ", width-l) + s
}

func printLanguages() {
	outer := "━"
	inner := "┃"

	outerWidth := 72
	innerWidth := 70
	nameW := 37
	extW := 31

	fmt.Println(strings.Repeat(outer, outerWidth))
	fmt.Printf("%s %s%s %s%s%s\n", inner,
		padRight("Language", nameW), " ",
		padRight("Extensions", extW),
		inner)
	fmt.Printf("%s%s%s\n", inner, strings.Repeat(outer, innerWidth), inner)

	// Get all languages sorted
	langs := getAllLanguagesSorted()

	for _, lang := range langs {
		exts := lang.Extensions
		extStr := strings.Join(exts, ", ")
		if len(extStr) > 30 {
			extStr = extStr[:27] + "..."
		}
		if extStr == "" {
			extStr = "<None>"
		}

		fmt.Printf("%s %s%s %s%s%s\n", inner,
			padRight(lang.Name, nameW), " ",
			padRight(extStr, extW-1)+" ",
			inner)
	}

	fmt.Println(strings.Repeat(outer, outerWidth))
	fmt.Println()
}

func getAllLanguagesSorted() []Language {
	var result []Language
	for i := range Languages {
		if len(Languages[i].Extensions) > 0 || len(Languages[i].Filenames) > 0 {
			result = append(result, Languages[i])
		}
	}
	// Sort alphabetically (case insensitive)
	sort.Slice(result, func(i, j int) bool {
		return strings.ToLower(result[i].Name) < strings.ToLower(result[j].Name)
	})
	return result
}
