// CountFileWithLang counts lines in file content for given language
func CountFileWithLang(content []byte, lang *Language) (LineStats, map[string]LineStats) {
	var mainStats LineStats
	mainStats.Children = nil

	children := make(map[string]LineStats)

	// Handle embedded languages (Markdown, Rust doc comments, etc.)
	if lang.HasChildren {
		return countWithChildren(content, lang, children)
	}

	scanner := bufio.NewScanner(bytes.NewReader(content))
	scanner.Buffer(make([]byte, 4*1024*1024), 4*1024*1024)

	state := &parserState{}
	comment := &lang.Comment

	for scanner.Scan() {
		line := scanner.Text()
		class := classifyLine(line, comment, state)
		switch class {
		case lineCode:
			mainStats.Code++
		case lineComment:
			mainStats.Comments++
		case lineBlank:
			mainStats.Blanks++
		}
	}

	return mainStats, children
}

// countWithChildren handles languages that can have embedded sub-languages
func countWithChildren(content []byte, lang *Language, children map[string]LineStats) (LineStats, map[string]LineStats) {
	var mainStats LineStats

	if lang.Name == "Markdown" || lang.Name == "Mdx" {
		return countMarkdown(content, lang, children)
	}

	if lang.Name == "Rust" {
		return countRust(content, lang, children)
	}

	// Default: just count normally
	scanner := bufio.NewScanner(bytes.NewReader(content))
	scanner.Buffer(make([]byte, 4*1024*1024), 4*1024*1024)

	state := &parserState{}
	comment := &lang.Comment

	for scanner.Scan() {
		line := scanner.Text()
		class := classifyLine(line, comment, state)
		switch class {
		case lineCode:
			mainStats.Code++
		case lineComment:
			mainStats.Comments++
		case lineBlank:
			mainStats.Blanks++
		}
	}

	return mainStats, children
}

// countMarkdown counts Markdown files, extracting code blocks as children
func countMarkdown(content []byte, lang *Language, children map[string]LineStats) (LineStats, map[string]LineStats) {
	var mainStats LineStats
	mainStats.Children = nil

	lines := splitLines(content)

	inCodeBlock := false
	var codeBlockLang string
	var codeBlockLines []string
	codeBlockFence := ""

	for _, line := range lines {
		trimmed := strings.TrimSpace(line)
		if !inCodeBlock {
			if strings.HasPrefix(trimmed, "```") || strings.HasPrefix(trimmed, "~~~") {
				fence := trimmed[:3]
				rest := strings.TrimSpace(trimmed[3:])
				// Extract language from code fence
				langName := strings.Fields(rest)
				if len(langName) > 0 {
					codeBlockLang = langName[0]
				} else {
					codeBlockLang = ""
				}
				inCodeBlock = true
				codeBlockFence = fence
				codeBlockLines = nil
				// The fence line itself counts as a comment in Markdown
				mainStats.Comments++
			} else if trimmed == "" {
				mainStats.Blanks++
			} else {
				mainStats.Comments++
			}
		} else {
			// In code block
			if strings.HasPrefix(trimmed, codeBlockFence) && strings.TrimSpace(trimmed[3:]) == "" {
				// End of code block
				inCodeBlock = false
				mainStats.Comments++ // closing fence is a comment

				// Process the code block
				if codeBlockLang != "" && len(codeBlockLines) > 0 {
					childLang := DetectLanguageByName(codeBlockLang)
					if childLang != nil {
						childContent := []byte(strings.Join(codeBlockLines, "\n") + "\n")
						childStats, _ := CountFileWithLang(childContent, childLang)
						existing := children[childLang.Name]
						existing.Code += childStats.Code
						existing.Comments += childStats.Comments
						existing.Blanks += childStats.Blanks
						children[childLang.Name] = existing
					} else {
						// Unknown language block, count as plain text
						for _, bl := range codeBlockLines {
							if strings.TrimSpace(bl) == "" {
								mainStats.Blanks++
							} else {
								mainStats.Comments++
							}
						}
					}
				} else {
					// No language specified, count as comments
					for _, bl := range codeBlockLines {
						if strings.TrimSpace(bl) == "" {
							mainStats.Blanks++
						} else {
							mainStats.Comments++
						}
					}
				}
			} else {
				codeBlockLines = append(codeBlockLines, line)
			}
		}
	}

	// Unclosed code block
	if inCodeBlock {
		for _, bl := range codeBlockLines {
			if strings.TrimSpace(bl) == "" {
				mainStats.Blanks++
			} else {
				mainStats.Comments++
			}
		}
	}

	return mainStats, children
}

// countRust counts Rust files with doc comments as Markdown children
func countRust(content []byte, lang *Language, children map[string]LineStats) (LineStats, map[string]LineStats) {
	var mainStats LineStats
	mainStats.Children = nil

	lines := splitLines(content)
	state := &parserState{}
	comment := &lang.Comment

	var mdLines []string
	inDocComment := false

	for _, line := range lines {
		trimmed := strings.TrimSpace(line)

		// Check if this line is a doc comment (/// ...)
		if strings.HasPrefix(trimmed, "///") {
			if !inDocComment {
				inDocComment = true
			}
			// Extract content after ///
			docContent := ""
			if len(trimmed) > 3 {
				docContent = trimmed[3:]
				if len(docContent) > 0 && docContent[0] == ' ' {
					docContent = docContent[1:]
				}
			}
			mdLines = append(mdLines, docContent)

			// Count as comment in main stats
			mainStats.Comments++
			continue
		}

		// If we were in a doc comment and now we're not
		if inDocComment {
			inDocComment = false
			// Process collected doc comment lines as Markdown
			if len(mdLines) > 0 {
				mdLang := FindLanguage("Markdown")
				if mdLang != nil {
					mdContent := []byte(strings.Join(mdLines, "\n") + "\n")
					mdStats, mdChildren := countMarkdown(mdContent, mdLang, make(map[string]LineStats))
					existing := children["Markdown"]
					existing.Code += mdStats.Code
					existing.Comments += mdStats.Comments
					existing.Blanks += mdStats.Blanks
					children["Markdown"] = existing
					// Add Markdown's children too
					for k, v := range mdChildren {
						ec := children[k]
						ec.Code += v.Code
						ec.Comments += v.Comments
						ec.Blanks += v.Blanks
						children[k] = ec
					}
				}
				mdLines = nil
			}
		}

		// Count the line normally
		class := classifyLine(line, comment, state)
		switch class {
		case lineCode:
			mainStats.Code++
		case lineComment:
			mainStats.Comments++
		case lineBlank:
			mainStats.Blanks++
		}
	}

	// Process remaining doc comment lines
	if len(mdLines) > 0 {
		mdLang := FindLanguage("Markdown")
		if mdLang != nil {
			mdContent := []byte(strings.Join(mdLines, "\n") + "\n")
			mdStats, mdChildren := countMarkdown(mdContent, mdLang, make(map[string]LineStats))
			existing := children["Markdown"]
			existing.Code += mdStats.Code
			existing.Comments += mdStats.Comments
			existing.Blanks += mdStats.Blanks
			children["Markdown"] = existing
			for k, v := range mdChildren {
				ec := children[k]
				ec.Code += v.Code
				ec.Comments += v.Comments
				ec.Blanks += v.Blanks
				children[k] = ec
			}
		}
	}

	return mainStats, children
}

func splitLines(content []byte) []string {
	scanner := bufio.NewScanner(bytes.NewReader(content))
	scanner.Buffer(make([]byte, 4*1024*1024), 4*1024*1024)
	var lines []string
	for scanner.Scan() {
		lines = append(lines, scanner.Text())
	}
	return lines
}

func FindLanguage(name string) *Language {
	for i := range Languages {
		if Languages[i].Name == name {
			return &Languages[i]
		}
	}
	return nil
}
