// classifyLine determines if a line is code, comment, or blank
// Returns: classification
// State is updated in place for multi-line tracking
func classifyLine(line string, comment *CommentStyle, state *parserState) lineClass {
	if comment == nil {
		if strings.TrimSpace(line) == "" {
			return lineBlank
		}
		return lineCode
	}

	// If we start inside a ML comment, this line is always COMMENT
	if state.inMLComment > 0 {
		// Scan for end of ML comment
		i := 0
		for i < len(line) {
			if state.inMLComment > 0 {
				closed := false
				for _, close := range comment.MultiClose {
					if len(close) == 0 {
						continue
					}
					if i+len(close) <= len(line) && line[i:i+len(close)] == close {
						state.inMLComment--
						i += len(close)
						closed = true
						break
					}
				}
				if closed {
					continue
				}
				// Check for nested open (if supported)
				if comment.NestedComments && len(comment.MultiOpen) > 0 {
					foundOpen := false
					for _, open := range comment.MultiOpen {
						if len(open) == 0 {
							continue
						}
						if i+len(open) <= len(line) && line[i:i+len(open)] == open {
							state.inMLComment++
							i += len(open)
							foundOpen = true
							break
						}
					}
					if foundOpen {
						continue
					}
				}
			}
			i++
		}
		return lineComment
	}

	// Parse line not starting in ML comment
	trimmed := strings.TrimSpace(line)
	if trimmed == "" {
		return lineBlank
	}

	// Track the position of the first comment start and last ML close
	// to determine line classification
	firstCommentStart := len(line) // position of first /* or // (while in OUT state)
	lastMLClose := -1              // position after last */
	hasSLAfterML := false          // has // after some closed */

	i := 0
	inML := 0
	inStr := false
	strChar := byte(0)

	for i < len(line) {
		if inStr {
			// In string, look for end
			c := line[i]
			if c == '\\' && i+1 < len(line) {
				i += 2 // skip escaped char
				continue
			}
			if c == strChar {
				inStr = false
			}
			i++
			continue
		}

		if inML > 0 {
			// In ML comment
			closed := false
			for _, close := range comment.MultiClose {
				if len(close) == 0 {
					continue
				}
				if i+len(close) <= len(line) && line[i:i+len(close)] == close {
					inML--
					if inML == 0 {
						lastMLClose = i + len(close)
					}
					i += len(close)
					closed = true
					break
				}
			}
			if closed {
				continue
			}
			// Check for nested open
			if comment.NestedComments {
				foundOpen := false
				for _, open := range comment.MultiOpen {
					if len(open) == 0 {
						continue
					}
					if i+len(open) <= len(line) && line[i:i+len(open)] == open {
						inML++
						i += len(open)
						foundOpen = true
						break
					}
				}
				if foundOpen {
					continue
				}
			}
			i++
			continue
		}

		// OUT state (not in comment, not in string)
		c := line[i]

		// Check for string start (basic - only handles " and ')
		// TODO: more complex string detection
		// For now, we skip string detection as tokei's main focus is comment detection

		// Check ML comment openers
		foundML := false
		for _, open := range comment.MultiOpen {
			if len(open) == 0 {
				continue
			}
			if i+len(open) <= len(line) && line[i:i+len(open)] == open {
				if i < firstCommentStart {
					firstCommentStart = i
				}
				inML++
				i += len(open)
				foundML = true
				break
			}
		}
		if foundML {
			continue
		}

		// Check SL comment markers
		foundSL := false
		for _, sl := range comment.Single {
			if len(sl) == 0 {
				continue
			}
			if i+len(sl) <= len(line) && line[i:i+len(sl)] == sl {
				if i < firstCommentStart {
					firstCommentStart = i
				}
				if lastMLClose >= 0 {
					hasSLAfterML = true
				}
				i = len(line) // jump to end
				foundSL = true
				break
			}
		}
		if foundSL {
			break
		}

		_ = c
		i++
	}

	// Update ML state for next line
	state.inMLComment = inML

	// Determine classification
	// Check for code before first comment start
	codeBeforeFirst := false
	for j := 0; j < firstCommentStart && j < len(line); j++ {
		b := line[j]
		if b != ' ' && b != '\t' && b != '\r' {
			codeBeforeFirst = true
			break
		}
	}
	if codeBeforeFirst {
		return lineCode
	}

	// Check for content after last ML close (includes SL comments!)
	if lastMLClose >= 0 {
		// Check if there's anything non-whitespace after lastMLClose
		for j := lastMLClose; j < len(line); j++ {
			b := line[j]
			if b != ' ' && b != '\t' && b != '\r' {
				// There's content after last ML close (could be code or SL comment)
				return lineCode
			}
		}
		// Nothing after last ML close
		if hasSLAfterML {
			return lineCode
		}
		return lineComment
	}

	// No ML comment at all, no code before first SL comment
	if firstCommentStart < len(line) {
		return lineComment
	}

	return lineBlank
}

