							i += len(open)
							foundOpen = true
							break
						}
					}
					if foundOpen {
						continue
					}
				}
			}
			i++
		}
		return lineComment
	}

	// Parse line not starting in ML comment
	trimmed := strings.TrimSpace(line)
	if trimmed == "" {
		return lineBlank
	}

	// Track the position of the first comment start and last ML close
	// to determine line classification
	firstCommentStart := len(line) // position of first /* or // (while in OUT state)
	lastMLClose := -1              // position after last */
	hasSLAfterML := false          // has // after some closed */

	i := 0
	inML := 0
	inStr := false
	strChar := byte(0)

	for i < len(line) {
		if inStr {
			// In string, look for end
			c := line[i]
			if c == '\\' && i+1 < len(line) {
				i += 2 // skip escaped char
				continue
			}
			if c == strChar {
				inStr = false
			}
			i++
			continue
		}

		if inML > 0 {
			// In ML comment
			closed := false
			for _, close := range comment.MultiClose {
				if len(close) == 0 {
					continue
				}
				if i+len(close) <= len(line) && line[i:i+len(close)] == close {
					inML--
					if inML == 0 {
						lastMLClose = i + len(close)
					}
					i += len(close)
					closed = true
					break
				}
			}
			if closed {
				continue
			}
			// Check for nested open
			if comment.NestedComments {
				foundOpen := false
				for _, open := range comment.MultiOpen {
					if len(open) == 0 {
						continue
					}
					if i+len(open) <= len(line) && line[i:i+len(open)] == open {
						inML++
						i += len(open)
						foundOpen = true
						break
					}
				}
				if foundOpen {
					continue
				}
			}
			i++
			continue
		}

		// OUT state (not in comment, not in string)
		c := line[i]

		// Check for string start (basic - only handles " and ')
		// TODO: more complex string detection
		// For now, we skip string detection as tokei's main focus is comment detection

		// Check ML comment openers
		foundML := false
		for _, open := range comment.MultiOpen {
			if len(open) == 0 {
				continue
			}
			if i+len(open) <= len(line) && line[i:i+len(open)] == open {
				if i < firstCommentStart {
					firstCommentStart = i
				}
				inML++
				i += len(open)
				foundML = true
				break
			}
		}
		if foundML {
			continue
		}

		// Check SL comment markers
		foundSL := false
		for _, sl := range comment.Single {
			if len(sl) == 0 {
				continue
			}
			if i+len(sl) <= len(line) && line[i:i+len(sl)] == sl {
				if i < firstCommentStart {
					firstCommentStart = i
				}
				if lastMLClose >= 0 {
					hasSLAfterML = true
				}
				i = len(line) // jump to end
				foundSL = true
				break
			}
		}
		if foundSL {
			break
		}

		_ = c
		i++
	}

	// Update ML state for next line
	state.inMLComment = inML

	// Determine classification
	// Check for code before first comment start
	codeBeforeFirst := false
	for j := 0; j < firstCommentStart && j < len(line); j++ {
		b := line[j]
		if b != ' ' && b != '\t' && b != '\r' {
			codeBeforeFirst = true
			break
		}
	}
	if codeBeforeFirst {
		return lineCode
	}

	// Check for content after last ML close (includes SL comments!)
	if lastMLClose >= 0 {
		// Check if there's anything non-whitespace after lastMLClose
		for j := lastMLClose; j < len(line); j++ {
			b := line[j]
			if b != ' ' && b != '\t' && b != '\r' {
				// There's content after last ML close (could be code or SL comment)
				return lineCode
			}
		}
		// Nothing after last ML close
		if hasSLAfterML {
			return lineCode
		}
		return lineComment
	}

	// No ML comment at all, no code before first SL comment
	if firstCommentStart < len(line) {
		return lineComment
	}

	return lineBlank
}

// CountFileWithLang counts lines in file content for given language
func CountFileWithLang(content []byte, lang *Language) (LineStats, map[string]LineStats) {
	var mainStats LineStats
	mainStats.Children = nil

	children := make(map[string]LineStats)

	// Handle embedded languages (Markdown, Rust doc comments, etc.)
	if lang.HasChildren {
		return countWithChildren(content, lang, children)
	}

	scanner := bufio.NewScanner(bytes.NewReader(content))
	scanner.Buffer(make([]byte, 4*1024*1024), 4*1024*1024)

	state := &parserState{}
	comment := &lang.Comment

	for scanner.Scan() {
		line := scanner.Text()
		class := classifyLine(line, comment, state)
		switch class {
		case lineCode:
			mainStats.Code++
		case lineComment:
			mainStats.Comments++
		case lineBlank:
			mainStats.Blanks++
		}
	}

	return mainStats, children
}

// countWithChildren handles languages that can have embedded sub-languages
func countWithChildren(content []byte, lang *Language, children map[string]LineStats) (LineStats, map[string]LineStats) {
	var mainStats LineStats

	if lang.Name == "Markdown" || lang.Name == "Mdx" {
		return countMarkdown(content, lang, children)
	}

	if lang.Name == "Rust" {
		return countRust(content, lang, children)
	}

	// Default: just count normally
	scanner := bufio.NewScanner(bytes.NewReader(content))
	scanner.Buffer(make([]byte, 4*1024*1024), 4*1024*1024)

	state := &parserState{}
	comment := &lang.Comment

	for scanner.Scan() {
		line := scanner.Text()
		class := classifyLine(line, comment, state)
		switch class {
		case lineCode:
			mainStats.Code++
		case lineComment:
			mainStats.Comments++
		case lineBlank:
			mainStats.Blanks++
		}
	}

	return mainStats, children
}

// countMarkdown counts Markdown files, extracting code blocks as children
func countMarkdown(content []byte, lang *Language, children map[string]LineStats) (LineStats, map[string]LineStats) {
	var mainStats LineStats
	mainStats.Children = nil

	lines := splitLines(content)

	inCodeBlock := false
	var codeBlockLang string
	var codeBlockLines []string
	codeBlockFence := ""

	for _, line := range lines {
		trimmed := strings.TrimSpace(line)
		if !inCodeBlock {
			if strings.HasPrefix(trimmed, "```") || strings.HasPrefix(trimmed, "~~~") {
				fence := trimmed[:3]
				rest := strings.TrimSpace(trimmed[3:])
				// Extract language from code fence
				langName := strings.Fields(rest)
				if len(langName) > 0 {
					codeBlockLang = langName[0]
				} else {
					codeBlockLang = ""
				}
				inCodeBlock = true
				codeBlockFence = fence
				codeBlockLines = nil
				// The fence line itself counts as a comment in Markdown
				mainStats.Comments++
			} else if trimmed == "" {
				mainStats.Blanks++
			} else {
				mainStats.Comments++
			}
		} else {
			// In code block
			if strings.HasPrefix(trimmed, codeBlockFence) && strings.TrimSpace(trimmed[3:]) == "" {
				// End of code block
				inCodeBlock = false
				mainStats.Comments++ // closing fence is a comment

				// Process the code block
				if codeBlockLang != "" && len(codeBlockLines) > 0 {
					childLang := DetectLanguageByName(codeBlockLang)
					if childLang != nil {
						childContent := []byte(strings.Join(codeBlockLines, "\n") + "\n")
						childStats, _ := CountFileWithLang(childContent, childLang)
						existing := children[childLang.Name]
						existing.Code += childStats.Code
						existing.Comments += childStats.Comments
						existing.Blanks += childStats.Blanks
						children[childLang.Name] = existing
					} else {
						// Unknown language block, count as plain text
						for _, bl := range codeBlockLines {
							if strings.TrimSpace(bl) == "" {
								mainStats.Blanks++
							} else {
								mainStats.Comments++
							}
						}
					}
				} else {
					// No language specified, count as comments
					for _, bl := range codeBlockLines {
						if strings.TrimSpace(bl) == "" {
							mainStats.Blanks++
						} else {
							mainStats.Comments++
						}
					}
				}
			} else {
				codeBlockLines = append(codeBlockLines, line)
			}
		}
	}

	// Unclosed code block
	if inCodeBlock {
		for _, bl := range codeBlockLines {
			if strings.TrimSpace(bl) == "" {
				mainStats.Blanks++
			} else {
				mainStats.Comments++
			}
		}
	}

	return mainStats, children
}

// countRust counts Rust files with doc comments as Markdown children
func countRust(content []byte, lang *Language, children map[string]LineStats) (LineStats, map[string]LineStats) {
	var mainStats LineStats
	mainStats.Children = nil

	lines := splitLines(content)
	state := &parserState{}
	comment := &lang.Comment

	var mdLines []string
	inDocComment := false

	for _, line := range lines {
		trimmed := strings.TrimSpace(line)

		// Check if this line is a doc comment (/// ...)
		if strings.HasPrefix(trimmed, "///") {
			if !inDocComment {
				inDocComment = true
			}
			// Extract content after ///
			docContent := ""
			if len(trimmed) > 3 {
				docContent = trimmed[3:]
				if len(docContent) > 0 && docContent[0] == ' ' {
					docContent = docContent[1:]
				}
			}
			mdLines = append(mdLines, docContent)

			// Count as comment in main stats
			mainStats.Comments++
			continue
		}

		// If we were in a doc comment and now we're not
		if inDocComment {
			inDocComment = false
			// Process collected doc comment lines as Markdown
			if len(mdLines) > 0 {
				mdLang := FindLanguage("Markdown")
				if mdLang != nil {
					mdContent := []byte(strings.Join(mdLines, "\n") + "\n")
					mdStats, mdChildren := countMarkdown(mdContent, mdLang, make(map[string]LineStats))
					existing := children["Markdown"]
					existing.Code += mdStats.Code
					existing.Comments += mdStats.Comments
					existing.Blanks += mdStats.Blanks
					children["Markdown"] = existing
					// Add Markdown's children too
					for k, v := range mdChildren {
						ec := children[k]
						ec.Code += v.Code
						ec.Comments += v.Comments
						ec.Blanks += v.Blanks
						children[k] = ec
					}
				}
				mdLines = nil
			}
		}

		// Count the line normally
		class := classifyLine(line, comment, state)
		switch class {
		case lineCode:
			mainStats.Code++
		case lineComment:
			mainStats.Comments++
		case lineBlank:
			mainStats.Blanks++
		}
	}

	// Process remaining doc comment lines
	if len(mdLines) > 0 {
		mdLang := FindLanguage("Markdown")
		if mdLang != nil {
			mdContent := []byte(strings.Join(mdLines, "\n") + "\n")
			mdStats, mdChildren := countMarkdown(mdContent, mdLang, make(map[string]LineStats))
			existing := children["Markdown"]
			existing.Code += mdStats.Code
			existing.Comments += mdStats.Comments
			existing.Blanks += mdStats.Blanks
			children["Markdown"] = existing
			for k, v := range mdChildren {
				ec := children[k]
				ec.Code += v.Code
				ec.Comments += v.Comments
				ec.Blanks += v.Blanks
				children[k] = ec
			}
		}
	}

	return mainStats, children
}

func splitLines(content []byte) []string {
	scanner := bufio.NewScanner(bytes.NewReader(content))
	scanner.Buffer(make([]byte, 4*1024*1024), 4*1024*1024)
	var lines []string
	for scanner.Scan() {
		lines = append(lines, scanner.Text())
	}
	return lines
}

func FindLanguage(name string) *Language {
	for i := range Languages {
		if Languages[i].Name == name {
			return &Languages[i]
		}
	}
	return nil
}
