// extensionMap maps file extensions to Language indices
var extensionMap map[string]*Language

// filenameMap maps exact filenames to Language indices
var filenameMap map[string]*Language

// DetectLanguageByName finds a language by its name or common identifier
func DetectLanguageByName(name string) *Language {
	nameLower := strings.ToLower(name)
	for i := range Languages {
		if strings.ToLower(Languages[i].Name) == nameLower {
			return &Languages[i]
		}
		// Also check some common aliases
	}
	return nil
}

// DetectLanguage detects the language based on file path
func DetectLanguage(path string) *Language {
	if extensionMap == nil {
		buildMaps()
	}

	base := filepath.Base(path)

	// Check exact filename first
	if lang, ok := filenameMap[base]; ok {
		return lang
	}

	// Check filename without leading dot (e.g., .gitignore -> gitignore)
	if strings.HasPrefix(base, ".") {
		if lang, ok := filenameMap[base[1:]]; ok {
			return lang
		}
	}

	// Get extension
	ext := filepath.Ext(path)
	if ext == "" {
		return nil
	}
	ext = strings.ToLower(ext[1:]) // remove leading dot

	if lang, ok := extensionMap[ext]; ok {
		return lang
	}

	return nil
}

func buildMaps() {
	extensionMap = make(map[string]*Language)
	filenameMap = make(map[string]*Language)

	for i := range Languages {
		lang := &Languages[i]

		// Register filenames
		for _, fn := range lang.Filenames {
			if _, exists := filenameMap[fn]; !exists {
				filenameMap[fn] = lang
			}
		}

		// Register extensions
		for _, ext := range lang.Extensions {
			extLower := strings.ToLower(ext)
			if _, exists := extensionMap[extLower]; !exists {
				extensionMap[extLower] = lang
			}
		}
	}
}
