package main

import (
	"bufio"
	"os"
	"path/filepath"
	"strings"
)

// Ignorer handles gitignore-style file filtering
type Ignorer struct {
	patterns []ignorePattern
	dir      string
}

type ignorePattern struct {
	pattern string
	negate  bool
	dirOnly bool
}

// NewIgnorer creates an Ignorer for the given directory
func NewIgnorer(dir string, cfg Config) *Ignorer {
	ig := &Ignorer{dir: dir}

	if !cfg.NoIgnore {
		// Load .gitignore if in VCS directory
		if !cfg.NoIgnoreVcs {
			ig.loadFile(filepath.Join(dir, ".gitignore"))
			ig.loadFile(filepath.Join(dir, ".hgignore"))
		}
		// Load .ignore and .tokeignore
		if !cfg.NoIgnoreDot {
			ig.loadFile(filepath.Join(dir, ".ignore"))
			ig.loadFile(filepath.Join(dir, ".tokeignore"))
		}
	}

	return ig
}

// ForSubdir creates a new Ignorer for a subdirectory, inheriting parent patterns
func (ig *Ignorer) ForSubdir(subdir string, cfg Config) *Ignorer {
	sub := &Ignorer{
		dir:      subdir,
		patterns: ig.patterns, // inherit parent patterns
	}

	if !cfg.NoIgnore {
		// Load subdirectory-specific ignore files
		if !cfg.NoIgnoreVcs {
			sub.loadFile(filepath.Join(subdir, ".gitignore"))
		}
		if !cfg.NoIgnoreDot {
			sub.loadFile(filepath.Join(subdir, ".ignore"))
			sub.loadFile(filepath.Join(subdir, ".tokeignore"))
		}
	}

	return sub
}

func (ig *Ignorer) loadFile(path string) {
	f, err := os.Open(path)
	if err != nil {
		return
	}
	defer f.Close()

	scanner := bufio.NewScanner(f)
	for scanner.Scan() {
		line := scanner.Text()
		// Skip comments and empty lines
		if strings.HasPrefix(line, "#") || strings.TrimSpace(line) == "" {
			continue
		}

		negate := false
		if strings.HasPrefix(line, "!") {
			negate = true
			line = line[1:]
		}

		dirOnly := strings.HasSuffix(line, "/")
		if dirOnly {
			line = line[:len(line)-1]
		}

		ig.patterns = append(ig.patterns, ignorePattern{
			pattern: line,
			negate:  negate,
			dirOnly: dirOnly,
		})
	}
}

// IsIgnored returns true if the path should be ignored
func (ig *Ignorer) IsIgnored(path string, isDir bool) bool {
	if ig == nil {
		return false
	}

	// Get relative path from ig.dir
	rel, err := filepath.Rel(ig.dir, path)
	if err != nil {
		rel = filepath.Base(path)
	}
	// Normalize to forward slashes
	rel = filepath.ToSlash(rel)
	name := filepath.Base(path)

	result := false

	for _, pat := range ig.patterns {
		if pat.dirOnly && !isDir {
			continue
		}

		matched := matchIgnorePattern(pat.pattern, rel, name)
		if matched {
			if pat.negate {
				result = false
			} else {
				result = true
			}
		}
	}

	return result
}

func matchIgnorePattern(pattern, relPath, name string) bool {
	// Handle patterns with forward slashes - match against full relative path
	if strings.Contains(pattern, "/") {
		matched, _ := filepath.Match(pattern, relPath)
		return matched
	}

	// No slash - match against just the filename
	matched, _ := filepath.Match(pattern, name)
	if matched {
		return true
	}

	// Also try matching the whole relative path component by component
	parts := strings.Split(relPath, "/")
	for _, part := range parts {
		m, _ := filepath.Match(pattern, part)
		if m {
			return true
		}
	}

	return false
}
