package main

import (
	"bufio"
	"bytes"
	"strings"
)

// LineStats holds statistics for a single file or language
type LineStats struct {
	Lines    int                  `json:"lines,omitempty"`
	Code     int                  `json:"code"`
	Comments int                  `json:"comments"`
	Blanks   int                  `json:"blanks"`
	Children map[string]LineStats `json:"blobs,omitempty"`
}

func (s LineStats) TotalLines() int {
	return s.Code + s.Comments + s.Blanks
}

// lineClass represents the classification of a line
type lineClass int

const (
	lineBlank   lineClass = iota
	lineCode
	lineComment
)

// parserState tracks state across lines
type parserState struct {
	inMLComment int // nesting depth of multi-line comment (0 = not in ML comment)
}

// classifyLine determines if a line is code, comment, or blank
// Returns: classification
// State is updated in place for multi-line tracking
func classifyLine(line string, comment *CommentStyle, state *parserState) lineClass {
	if comment == nil {
		if strings.TrimSpace(line) == "" {
			return lineBlank
		}
		return lineCode
	}

	// If we start inside a ML comment, this line is always COMMENT
	if state.inMLComment > 0 {
		// Scan for end of ML comment
		i := 0
		for i < len(line) {
			if state.inMLComment > 0 {
				closed := false
				for _, close := range comment.MultiClose {
					if len(close) == 0 {
						continue
					}
					if i+len(close) <= len(line) && line[i:i+len(close)] == close {
						state.inMLComment--
						i += len(close)
						closed = true
						break
					}
				}
				if closed {
					continue
				}
				// Check for nested open (if supported)
				if comment.NestedComments && len(comment.MultiOpen) > 0 {
					foundOpen := false
					for _, open := range comment.MultiOpen {
						if len(open) == 0 {
							continue
						}
						if i+len(open) <= len(line) && line[i:i+len(open)] == open {
							state.inMLComment++
							i += len(open)
							foundOpen = true
							break
						}
					}
					if foundOpen {
						continue
					}
				}
			}
			i++
		}
		return lineComment
	}

	// Parse line not starting in ML comment
	trimmed := strings.TrimSpace(line)
	if trimmed == "" {
		return lineBlank
	}

	// Track the position of the first comment start and last ML close
	firstCommentStart := len(line)
	lastMLClose := -1
	hasSLAfterML := false

	i := 0
	inML := 0
	inStr := false
	strChar := byte(0)
	inBacktick := false // Go raw strings

	for i < len(line) {
		// Handle backtick raw strings (Go-specific, no escapes)
		if inBacktick {
			if line[i] == '`' {
				inBacktick = false
			}
			i++
			continue
		}

		// Handle regular strings
		if inStr {
			c := line[i]
			if c == '\\' && i+1 < len(line) {
				i += 2 // skip escaped char
				continue
			}
			if c == strChar {
				inStr = false
			}
			i++
			continue
		}

		if inML > 0 {
			// In ML comment
			closed := false
			for _, close := range comment.MultiClose {
				if len(close) == 0 {
					continue
				}
				if i+len(close) <= len(line) && line[i:i+len(close)] == close {
					inML--
					if inML == 0 {
						lastMLClose = i + len(close)
					}
					i += len(close)
					closed = true
					break
				}
			}
			if closed {
				continue
			}
			// Check for nested open
			if comment.NestedComments {
				foundOpen := false
				for _, open := range comment.MultiOpen {
					if len(open) == 0 {
						continue
					}
					if i+len(open) <= len(line) && line[i:i+len(open)] == open {
						inML++
						i += len(open)
						foundOpen = true
						break
					}
				}
				if foundOpen {
					continue
				}
			}
			i++
			continue
		}

		// OUT state (not in comment, not in string)
		c := line[i]

		// Check for string start
		if c == '"' || c == '\'' {
			inStr = true
			strChar = c
			i++
			continue
		}
		if c == '`' {
			inBacktick = true
			i++
			continue
		}

		// Check ML comment openers
		foundML := false
		for _, open := range comment.MultiOpen {
			if len(open) == 0 {
				continue
			}
			if i+len(open) <= len(line) && line[i:i+len(open)] == open {
				if i < firstCommentStart {
					firstCommentStart = i
				}
				inML++
				i += len(open)
				foundML = true
				break
			}
		}
		if foundML {
			continue
		}

		// Check SL comment markers
		foundSL := false
		for _, sl := range comment.Single {
			if len(sl) == 0 {
				continue
			}
			if i+len(sl) <= len(line) && line[i:i+len(sl)] == sl {
				if i < firstCommentStart {
					firstCommentStart = i
				}
				if lastMLClose >= 0 {
					hasSLAfterML = true
				}
				i = len(line)
				foundSL = true
				break
			}
		}
		if foundSL {
			break
		}

		i++
	}

	// Update ML state for next line
	state.inMLComment = inML

	// Determine classification
	codeBeforeFirst := false
	for j := 0; j < firstCommentStart && j < len(line); j++ {
		b := line[j]
		if b != ' ' && b != '\t' && b != '\r' {
			codeBeforeFirst = true
			break
		}
	}
	if codeBeforeFirst {
		return lineCode
	}

	if lastMLClose >= 0 {
		for j := lastMLClose; j < len(line); j++ {
			b := line[j]
			if b != ' ' && b != '\t' && b != '\r' {
				return lineCode
			}
		}
		if hasSLAfterML {
			return lineCode
		}
		return lineComment
	}

	if firstCommentStart < len(line) {
		return lineComment
	}

	return lineBlank
}

// CountFileWithLang counts lines in file content for given language
func CountFileWithLang(content []byte, lang *Language) (LineStats, map[string]LineStats) {
	var mainStats LineStats
	mainStats.Children = nil

	children := make(map[string]LineStats)

	if lang.HasChildren {
		return countWithChildren(content, lang, children)
	}

	scanner := bufio.NewScanner(bytes.NewReader(content))
	scanner.Buffer(make([]byte, 4*1024*1024), 4*1024*1024)

	state := &parserState{}
	comment := &lang.Comment

	for scanner.Scan() {
		line := scanner.Text()
		class := classifyLine(line, comment, state)
		switch class {
		case lineCode:
			mainStats.Code++
		case lineComment:
			mainStats.Comments++
		case lineBlank:
			mainStats.Blanks++
		}
	}

	return mainStats, children
}

func countWithChildren(content []byte, lang *Language, children map[string]LineStats) (LineStats, map[string]LineStats) {
	var mainStats LineStats

	if lang.Name == "Markdown" || lang.Name == "Mdx" {
		return countMarkdown(content, lang, children)
	}

	if lang.Name == "Rust" {
		return countRust(content, lang, children)
	}

	// Default: just count normally
	scanner := bufio.NewScanner(bytes.NewReader(content))
	scanner.Buffer(make([]byte, 4*1024*1024), 4*1024*1024)

	state := &parserState{}
	comment := &lang.Comment

	for scanner.Scan() {
		line := scanner.Text()
		class := classifyLine(line, comment, state)
		switch class {
		case lineCode:
			mainStats.Code++
		case lineComment:
			mainStats.Comments++
		case lineBlank:
			mainStats.Blanks++
		}
	}

	return mainStats, children
}

func countMarkdown(content []byte, lang *Language, children map[string]LineStats) (LineStats, map[string]LineStats) {
	var mainStats LineStats
	mainStats.Children = nil

	lines := splitLines(content)

	inCodeBlock := false
	var codeBlockLang string
	var codeBlockLines []string
	codeBlockFence := ""

	for _, line := range lines {
		trimmed := strings.TrimSpace(line)
		if !inCodeBlock {
			if strings.HasPrefix(trimmed, "```") || strings.HasPrefix(trimmed, "~~~") {
				fence := trimmed[:3]
				rest := strings.TrimSpace(trimmed[3:])
				langName := strings.Fields(rest)
				if len(langName) > 0 {
					codeBlockLang = langName[0]
				} else {
					codeBlockLang = ""
				}
				inCodeBlock = true
				codeBlockFence = fence
				codeBlockLines = nil
				mainStats.Comments++
			} else if trimmed == "" {
				mainStats.Blanks++
			} else {
				mainStats.Comments++
			}
		} else {
			if strings.HasPrefix(trimmed, codeBlockFence) && strings.TrimSpace(trimmed[3:]) == "" {
				inCodeBlock = false
				mainStats.Comments++

				if codeBlockLang != "" && len(codeBlockLines) > 0 {
					childLang := DetectLanguageByName(codeBlockLang)
					if childLang != nil {
						childContent := []byte(strings.Join(codeBlockLines, "\n") + "\n")
						childStats, _ := CountFileWithLang(childContent, childLang)
						existing := children[childLang.Name]
						existing.Code += childStats.Code
						existing.Comments += childStats.Comments
						existing.Blanks += childStats.Blanks
						children[childLang.Name] = existing
					} else {
						for _, bl := range codeBlockLines {
							if strings.TrimSpace(bl) == "" {
								mainStats.Blanks++
							} else {
								mainStats.Comments++
							}
						}
					}
				} else {
					for _, bl := range codeBlockLines {
						if strings.TrimSpace(bl) == "" {
							mainStats.Blanks++
						} else {
							mainStats.Comments++
						}
					}
				}
			} else {
				codeBlockLines = append(codeBlockLines, line)
			}
		}
	}

	if inCodeBlock {
		for _, bl := range codeBlockLines {
			if strings.TrimSpace(bl) == "" {
				mainStats.Blanks++
			} else {
				mainStats.Comments++
			}
		}
	}

	return mainStats, children
}

func countRust(content []byte, lang *Language, children map[string]LineStats) (LineStats, map[string]LineStats) {
	var mainStats LineStats
	mainStats.Children = nil

	lines := splitLines(content)
	state := &parserState{}
	comment := &lang.Comment

	var mdLines []string
	inDocComment := false

	for _, line := range lines {
		trimmed := strings.TrimSpace(line)

		if strings.HasPrefix(trimmed, "///") {
			if !inDocComment {
				inDocComment = true
			}
			docContent := ""
			if len(trimmed) > 3 {
				docContent = trimmed[3:]
				if len(docContent) > 0 && docContent[0] == ' ' {
					docContent = docContent[1:]
				}
			}
			mdLines = append(mdLines, docContent)
			mainStats.Comments++
			continue
		}

		if inDocComment {
			inDocComment = false
			if len(mdLines) > 0 {
				mdLang := FindLanguage("Markdown")
				if mdLang != nil {
					mdContent := []byte(strings.Join(mdLines, "\n") + "\n")
					mdStats, mdChildren := countMarkdown(mdContent, mdLang, make(map[string]LineStats))
					existing := children["Markdown"]
					existing.Code += mdStats.Code
					existing.Comments += mdStats.Comments
					existing.Blanks += mdStats.Blanks
					children["Markdown"] = existing
					for k, v := range mdChildren {
						ec := children[k]
						ec.Code += v.Code
						ec.Comments += v.Comments
						ec.Blanks += v.Blanks
						children[k] = ec
					}
				}
				mdLines = nil
			}
		}

		class := classifyLine(line, comment, state)
		switch class {
		case lineCode:
			mainStats.Code++
		case lineComment:
			mainStats.Comments++
		case lineBlank:
			mainStats.Blanks++
		}
	}

	if len(mdLines) > 0 {
