// FileReport holds stats for a single file
type FileReport struct {
	Name  string    `json:"name"`
	Stats LineStats `json:"stats"`
}

func (f FileReport) MarshalJSON() ([]byte, error) {
	type Inner struct {
		Blanks   int                  `json:"blanks"`
		Code     int                  `json:"code"`
		Comments int                  `json:"comments"`
		Blobs    map[string]LineStats `json:"blobs"`
	}
	type Alias struct {
		Stats Inner  `json:"stats"`
		Name  string `json:"name"`
	}
	a := Alias{Name: f.Name}
	a.Stats.Blanks = f.Stats.Blanks
	a.Stats.Code = f.Stats.Code
	a.Stats.Comments = f.Stats.Comments
	blobs := f.Stats.Children
	if blobs == nil {
		blobs = map[string]LineStats{}
	}
	// Serialize blobs without the Children field
	a.Stats.Blobs = blobs
	return json.Marshal(a)
}

// LanguageStats holds aggregated stats for a language
type LanguageStats struct {
	Blanks     int                     `json:"blanks"`
	Code       int                     `json:"code"`
	Comments   int                     `json:"comments"`
	Reports    []FileReport            `json:"reports"`
	Children   map[string][]FileReport `json:"children"`
	Inaccurate bool                    `json:"inaccurate"`
}

func newLanguageStats() LanguageStats {
	return LanguageStats{
		Reports:  []FileReport{},
		Children: map[string][]FileReport{},
	}
}

func (s LanguageStats) TotalLines() int {
	return s.Code + s.Comments + s.Blanks
}

func (s LanguageStats) Files() int {
	return len(s.Reports)
}

// Total lines including children
func (s LanguageStats) TotalLinesWithChildren() int {
	total := s.TotalLines()
	for _, reports := range s.Children {
		for _, r := range reports {
			total += r.Stats.TotalLines()
		}
	}
	return total
