func main() {
	cfg := parseArgs(os.Args[1:])

	if cfg.Languages {
		printLanguages()
		return
	}

	if cfg.Columns == 0 {
		cfg.Columns = 81
	}

	var langFilter map[string]bool
	if len(cfg.Types) > 0 {
		langFilter = make(map[string]bool)
		for _, t := range cfg.Types {
			langFilter[t] = true
		}
	}

	stats := make(map[string]LanguageStats)

	paths := cfg.Paths
	if len(paths) == 0 {
		paths = []string{"."}
	}

	for _, path := range paths {
		fi, err := os.Stat(path)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: %q not found.\n", path)
			os.Exit(1)
		}

		if fi.IsDir() {
			ignorer := NewIgnorer(path, cfg)
			walkDir(path, path, ignorer, cfg, langFilter, stats)
		} else {
			processFile(path, path, cfg, langFilter, stats)
		}
	}

	if cfg.Output == "json" {
		outputJSON(stats)
		return
	}

	if cfg.Streaming == "json" || cfg.Streaming == "simple" {
		outputStreaming(stats, cfg.Streaming)
		return
	}

	printTable(stats, cfg)
}

func parseArgs(args []string) Config {
	cfg := Config{}

	i := 0
	for i < len(args) {
		arg := args[i]
		switch {
		case arg == "-h" || arg == "--help":
			printHelp()
			os.Exit(0)
		case arg == "-V" || arg == "--version":
			fmt.Println("tokei 14.0.0 compiled with serialization support: json")
			os.Exit(0)
		case arg == "-l" || arg == "--languages":
			cfg.Languages = true
		case arg == "-f" || arg == "--files":
			cfg.Files = true
		case arg == "--hidden":
			cfg.Hidden = true
		case arg == "--no-ignore":
			cfg.NoIgnore = true
			cfg.NoIgnoreVcs = true
			cfg.NoIgnoreDot = true
			cfg.NoIgnoreParent = true
		case arg == "--no-ignore-vcs":
			cfg.NoIgnoreVcs = true
		case arg == "--no-ignore-dot":
			cfg.NoIgnoreDot = true
		case arg == "--no-ignore-parent":
			cfg.NoIgnoreParent = true
		case arg == "-C" || arg == "--compact":
			cfg.Compact = true
		case arg == "-v" || arg == "--verbose":
			cfg.Verbose++
		case strings.HasPrefix(arg, "-vvv"):
			cfg.Verbose = 3
		case strings.HasPrefix(arg, "-vv"):
			cfg.Verbose = 2
		case arg == "-s" || arg == "--sort":
			i++
			if i < len(args) {
				cfg.Sort = args[i]
			}
		case strings.HasPrefix(arg, "--sort="):
			cfg.Sort = arg[len("--sort="):]
		case strings.HasPrefix(arg, "-s="):
			cfg.Sort = arg[3:]
		case arg == "-r" || arg == "--rsort":
			i++
			if i < len(args) {
				cfg.Rsort = args[i]
			}
		case strings.HasPrefix(arg, "--rsort="):
			cfg.Rsort = arg[len("--rsort="):]
		case arg == "-o" || arg == "--output":
			i++
			if i < len(args) {
				cfg.Output = args[i]
			}
		case strings.HasPrefix(arg, "--output="):
			cfg.Output = arg[len("--output="):]
		case strings.HasPrefix(arg, "--streaming="):
			cfg.Streaming = arg[len("--streaming="):]
		case arg == "--streaming":
			i++
			if i < len(args) {
				cfg.Streaming = args[i]
			}
		case arg == "-t" || arg == "--types":
			i++
			if i < len(args) {
				for _, t := range strings.Split(args[i], ",") {
					if t = strings.TrimSpace(t); t != "" {
						cfg.Types = append(cfg.Types, t)
					}
				}
			}
		case strings.HasPrefix(arg, "--types="):
			for _, t := range strings.Split(arg[8:], ",") {
				if t = strings.TrimSpace(t); t != "" {
					cfg.Types = append(cfg.Types, t)
				}
			}
		case strings.HasPrefix(arg, "-t="):
			for _, t := range strings.Split(arg[3:], ",") {
				if t = strings.TrimSpace(t); t != "" {
					cfg.Types = append(cfg.Types, t)
				}
			}
		case arg == "-c" || arg == "--columns":
			i++
			if i < len(args) {
				if n, err := strconv.Atoi(args[i]); err == nil {
					cfg.Columns = n
				}
			}
		case strings.HasPrefix(arg, "--columns="):
			if n, err := strconv.Atoi(arg[10:]); err == nil {
				cfg.Columns = n
			}
		case arg == "-e" || arg == "--exclude":
			i++
			if i < len(args) {
				cfg.Exclude = append(cfg.Exclude, args[i])
			}
		case strings.HasPrefix(arg, "--exclude="):
			cfg.Exclude = append(cfg.Exclude, arg[10:])
		case arg == "-i" || arg == "--input":
			i++
			if i < len(args) {
				cfg.Input = args[i]
			}
		case strings.HasPrefix(arg, "--input="):
			cfg.Input = arg[8:]
		case arg == "-n" || arg == "--num-format":
			i++
			if i < len(args) {
				cfg.NumFormat = args[i]
			}
		case strings.HasPrefix(arg, "--num-format="):
			cfg.NumFormat = arg[len("--num-format="):]
		case arg == "--":
			i++
			cfg.Paths = append(cfg.Paths, args[i:]...)
			return cfg
		case strings.HasPrefix(arg, "-"):
			// Unknown flag
		default:
			cfg.Paths = append(cfg.Paths, arg)
		}
		i++
	}

	if cfg.Input != "" {
		fmt.Fprintf(os.Stderr, "Error:\n Failed to parse input file: %s\n\nThis version of tokei was compiled without any 'yaml' serialization support, to enable serialization, reinstall tokei with the features flag.\n\n    cargo install tokei --features yaml\n\nIf you want to enable all supported serialization formats, you can use the 'all' feature.\n\n    cargo install tokei --features all\n    \n", cfg.Input)
		os.Exit(1)
	}

	return cfg
}

