				numW, r.lines,
				numW, r.code,
				numW, r.comments,
				numW, r.blanks)
		}
	}
}

func getSortedLangNames(stats map[string]LanguageStats, sortBy string, rsortBy string) []string {
	names := make([]string, 0, len(stats))
	for k := range stats {
		names = append(names, k)
	}

	sortField := sortBy
	if rsortBy != "" {
		sortField = rsortBy
	}

	switch sortField {
	case "files":
		sort.Slice(names, func(i, j int) bool {
			a, b := stats[names[i]].Files(), stats[names[j]].Files()
			if a != b {
				if rsortBy != "" {
					return a > b
				}
				return a < b
			}
			return names[i] < names[j]
		})
	case "lines":
		sort.Slice(names, func(i, j int) bool {
			a := stats[names[i]].TotalLinesWithChildren()
			b := stats[names[j]].TotalLinesWithChildren()
			if a != b {
				if rsortBy != "" {
					return a > b
				}
				return a < b
			}
			return names[i] < names[j]
		})
	case "code":
		sort.Slice(names, func(i, j int) bool {
			a := stats[names[i]].TotalCodeWithChildren()
			b := stats[names[j]].TotalCodeWithChildren()
			if a != b {
				if rsortBy != "" {
					return a > b
				}
				return a < b
			}
			return names[i] < names[j]
		})
	case "comments":
		sort.Slice(names, func(i, j int) bool {
			a := stats[names[i]].TotalCommentsWithChildren()
			b := stats[names[j]].TotalCommentsWithChildren()
			if a != b {
				if rsortBy != "" {
					return a > b
				}
				return a < b
			}
			return names[i] < names[j]
		})
	case "blanks":
		sort.Slice(names, func(i, j int) bool {
			a := stats[names[i]].TotalBlanksWithChildren()
			b := stats[names[j]].TotalBlanksWithChildren()
			if a != b {
				if rsortBy != "" {
					return a > b
				}
				return a < b
			}
			return names[i] < names[j]
		})
	default:
		sort.Strings(names)
	}

	return names
}

func formatNum(n int, style string) string {
	s := strconv.Itoa(n)
	if style == "" || style == "plain" {
		return s
	}

	var sep string
	switch style {
	case "commas":
		sep = ","
	case "dots":
		sep = "."
	case "underscores":
		sep = "_"
	default:
		return s
	}

	runes := []rune(s)
	result := make([]rune, 0, len(runes)*2)
	for i, r := range runes {
		pos := len(runes) - i
		if i > 0 && pos%3 == 0 {
			result = append(result, []rune(sep)...)
		}
		result = append(result, r)
	}
	return string(result)
}

func printTable(stats map[string]LanguageStats, cfg Config) {
	cols := cfg.Columns
	langW := cols - 67
	if langW < 1 {
		langW = 1
	}

	thick := strings.Repeat("━", cols)
	thin := strings.Repeat("─", cols)

	fmt.Println(thick)
	header := " " + padRight("Language", langW) + padLeft("Files", 13) + padLeft("Lines", 13) + padLeft("Code", 13) + padLeft("Comments", 13) + padLeft("Blanks", 13)
	fmt.Println(header)
	fmt.Println(thick)

	langNames := getSortedLangNames(stats, cfg.Sort, cfg.Rsort)

	// Separate languages into those with and without children
	// (when compact mode: treat all as having no children)
	var noChildNames, childNames []string
	for _, n := range langNames {
		ls := stats[n]
		hasChildren := !cfg.Compact && len(ls.Children) > 0
		if hasChildren {
			childNames = append(childNames, n)
		} else {
			noChildNames = append(noChildNames, n)
		}
	}

	// Rebuild ordered list: no-child names first, then child names
	// BUT only if we're using default sort (alphabetical)
	// If sorting by column, keep the original order but apply separators
	var orderedNames []string
	if cfg.Sort == "" && cfg.Rsort == "" {
		orderedNames = append(orderedNames, noChildNames...)
		orderedNames = append(orderedNames, childNames...)
	} else {
		orderedNames = langNames
	}

	// Track totals
	var totalCode, totalComments, totalBlanks, totalFiles int

	firstLang := true

	for _, langName := range orderedNames {
		ls := stats[langName]
		hasChildren := !cfg.Compact && len(ls.Children) > 0

		// Print thin separator before languages with children
		// (but not before the very first language)
		if hasChildren && !firstLang {
			fmt.Println(thin)
		}
		firstLang = false

		// If --files is specified, print thin separator before each language
		// (as part of the files section)
		if cfg.Files && !hasChildren {
			// Will be printed after the lang row
		}

		files := ls.Files()
		linesNoChildren := ls.TotalLines()
		linesWithChildren := ls.TotalLinesWithChildren()

		// For the language row: show lines WITH children
		displayLines := linesWithChildren

		fmt.Printf(" %s%s%s%s%s%s\n",
			padRight(langName, langW),
			padLeft(formatNum(files, cfg.NumFormat), 13),
			padLeft(formatNum(displayLines, cfg.NumFormat), 13),
			padLeft(formatNum(ls.TotalCodeWithChildren(), cfg.NumFormat), 13),
			padLeft(formatNum(ls.TotalCommentsWithChildren(), cfg.NumFormat), 13),
			padLeft(formatNum(ls.TotalBlanksWithChildren(), cfg.NumFormat), 13))

		// Print child language rows (sub-language summary)
		if hasChildren {
			childLangNames := make([]string, 0, len(ls.Children))
			for cn := range ls.Children {
				childLangNames = append(childLangNames, cn)
			}
			sort.Strings(childLangNames)

			for _, cn := range childLangNames {
				childReports := ls.Children[cn]
				var cCode, cComments, cBlanks int
				for _, r := range childReports {
					cCode += r.Stats.Code
					cComments += r.Stats.Comments
					cBlanks += r.Stats.Blanks
				}
				cFiles := len(childReports)
				cLines := cCode + cComments + cBlanks

				childLabel := "|- " + cn
				fmt.Printf(" %s%s%s%s%s%s\n",
					padRight(childLabel, langW),
					padLeft(formatNum(cFiles, cfg.NumFormat), 13),
					padLeft(formatNum(cLines, cfg.NumFormat), 13),
					padLeft(formatNum(cCode, cfg.NumFormat), 13),
					padLeft(formatNum(cComments, cfg.NumFormat), 13),
					padLeft(formatNum(cBlanks, cfg.NumFormat), 13))
			}

			// Print (Total) row
			fmt.Printf(" %s%s%s%s%s%s\n",
				padRight("(Total)", langW),
				padLeft("", 13),
				padLeft(formatNum(linesWithChildren, cfg.NumFormat), 13),
				padLeft(formatNum(ls.TotalCodeWithChildren(), cfg.NumFormat), 13),
				padLeft(formatNum(ls.TotalCommentsWithChildren(), cfg.NumFormat), 13),
				padLeft(formatNum(ls.TotalBlanksWithChildren(), cfg.NumFormat), 13))
		}

		// Print files if --files is specified
		if cfg.Files {
			fmt.Println(thin)
			for _, report := range ls.Reports {
				children := report.Stats.Children
				if len(children) > 0 {
					// File with embedded children
					fmt.Printf(" %s\n", report.Name)
					childLangNames2 := make([]string, 0, len(children))
					for cn := range children {
						childLangNames2 = append(childLangNames2, cn)
					}
					sort.Strings(childLangNames2)

					// First show parent lang's stats
					// In tokei's output, first sub-entry is the parent lang
					parentLines := report.Stats.TotalLines()
					fmt.Printf(" %s%s%s%s%s\n",
						padRight("|- "+langName, langW+13),
						padLeft(formatNum(parentLines, cfg.NumFormat), 13),
						padLeft(formatNum(report.Stats.Code, cfg.NumFormat), 13),
						padLeft(formatNum(report.Stats.Comments, cfg.NumFormat), 13),
						padLeft(formatNum(report.Stats.Blanks, cfg.NumFormat), 13))

					for _, cn := range childLangNames2 {
						cs := children[cn]
						cLines := cs.TotalLines()
						fmt.Printf(" %s%s%s%s%s\n",
							padRight("|- "+cn, langW+13),
							padLeft(formatNum(cLines, cfg.NumFormat), 13),
							padLeft(formatNum(cs.Code, cfg.NumFormat), 13),
							padLeft(formatNum(cs.Comments, cfg.NumFormat), 13),
							padLeft(formatNum(cs.Blanks, cfg.NumFormat), 13))
					}

					// File total = parent lang stats only (not children)
					fmt.Printf(" %s%s%s%s%s\n",
						padRight(report.Name, langW+13),
						padLeft(formatNum(parentLines, cfg.NumFormat), 13),
						padLeft(formatNum(report.Stats.Code, cfg.NumFormat), 13),
						padLeft(formatNum(report.Stats.Comments, cfg.NumFormat), 13),
						padLeft(formatNum(report.Stats.Blanks, cfg.NumFormat), 13))
				} else {
					fileLines := report.Stats.TotalLines()
					fmt.Printf(" %s%s%s%s%s\n",
						padRight(report.Name, langW+13),
						padLeft(formatNum(fileLines, cfg.NumFormat), 13),
						padLeft(formatNum(report.Stats.Code, cfg.NumFormat), 13),
						padLeft(formatNum(report.Stats.Comments, cfg.NumFormat), 13),
						padLeft(formatNum(report.Stats.Blanks, cfg.NumFormat), 13))
				}
			}
			// Only print thin separator if this is NOT the last language
			// We'll handle this by checking if there are more languages after
		}

		_ = linesNoChildren

		// Accumulate totals (includes children)
		totalCode += ls.TotalCodeWithChildren()
		totalComments += ls.TotalCommentsWithChildren()
		totalBlanks += ls.TotalBlanksWithChildren()
		totalFiles += files
	}

	totalLines := totalCode + totalComments + totalBlanks
	fmt.Println(thick)
	fmt.Printf(" %s%s%s%s%s%s\n",
		padRight("Total", langW),
		padLeft(formatNum(totalFiles, cfg.NumFormat), 13),
		padLeft(formatNum(totalLines, cfg.NumFormat), 13),
		padLeft(formatNum(totalCode, cfg.NumFormat), 13),
		padLeft(formatNum(totalComments, cfg.NumFormat), 13),
		padLeft(formatNum(totalBlanks, cfg.NumFormat), 13))
	fmt.Println(thick)
}

func padRight(s string, width int) string {
	l := utf8.RuneCountInString(s)
	if l >= width {
		runes := []rune(s)
		if len(runes) > width {
			return string(runes[:width])
		}
		return s
	}
	return s + strings.Repeat(" ", width-l)
}

func padLeft(s string, width int) string {
	l := utf8.RuneCountInString(s)
	if l >= width {
		return s
	}
	return strings.Repeat(" ", width-l) + s
}

func printLanguages() {
	outerWidth := 72
	innerWidth := 70
	nameW := 37
	extW := 31

	fmt.Println(strings.Repeat("━", outerWidth))
	fmt.Printf("┃ %s %s┃\n",
		padRight("Language", nameW)+" ",
		padRight("Extensions", extW-1)+" ")
	fmt.Printf("┃%s┃\n", strings.Repeat("━", innerWidth))

	langs := getAllLanguagesSorted()

	for _, lang := range langs {
		exts := lang.Extensions
		extStr := strings.Join(exts, ", ")
		if len(extStr) > 30 {
			extStr = extStr[:27] + "..."
		}
		if extStr == "" {
			extStr = "<None>"
		}

		fmt.Printf("┃ %s %s┃\n",
			padRight(lang.Name, nameW)+" ",
			padRight(extStr, extW-1)+" ")
	}

	fmt.Println(strings.Repeat("━", outerWidth))
	fmt.Println()
}

func getAllLanguagesSorted() []Language {
	var result []Language
	seen := make(map[string]bool)
	for i := range Languages {
		if seen[Languages[i].Name] {
			continue
		}
		if len(Languages[i].Extensions) > 0 || len(Languages[i].Filenames) > 0 {
			result = append(result, Languages[i])
			seen[Languages[i].Name] = true
		}
	}
	sort.Slice(result, func(i, j int) bool {
		return strings.ToLower(result[i].Name) < strings.ToLower(result[j].Name)
	})
	return result
}
